insert into public.service_qualification_questions(service_code,question_key,question_text,input_type,required,sort_order) select 'HR-TEMP-STAFFING',question_key,question_text,input_type,required,sort_order from public.service_qualification_questions where service_code='TEMP_OUTSOURCING' on conflict(service_code,question_key) do update set question_text=excluded.question_text,input_type=excluded.input_type,required=excluded.required,sort_order=excluded.sort_order,active=true,updated_at=now();